function renderGallery(){
 const team=viewTeamId();
 const current=galleryStates.find(x=>x.team_id===team)||{};
 const canSkip=teacherPreview||!!current.completed_at;
 mountGallery($("#view"),{
   initial:teacherPreview?{}:current,preview:demo||teacherPreview,
   draftKey:(!demo&&!teacherPreview&&user?.id)?'inperialismoa:gallery:draft:'+user.id+':'+team:null,
   canSkip,navigationEnabled:teacherPreview,navigationPreview:teacherPreview,
   dossierProgress:()=>m1Pieces(team).size,
   onBack:()=>{galleryQuestionsOpen=false;currentMission=0;render()},
   onContinue:()=>{if(teacherPreview){location.assign("./bi-sistema.html?preview=1")}else if(demo){galleryQuestionsOpen=true;render()}else location.assign("./bi-sistema.html")},
   onSubmit:async answers=>{
     const {data,error}=await db.rpc("submit_gallery_attempt",{p_answers:answers});
     if(error)throw error;
     const {data:rows,error:stateError}=await db.from("gallery_team_state").select("team_id,locked_ids,locked_positions,completed_at,updated_at").eq("team_id",team);
     if(!stateError&&rows?.length)galleryStates=[...galleryStates.filter(x=>x.team_id!==team),rows[0]];
     return data;
   }
 });
}
function renderMission(){if(currentMission===2&&!demo){location.assign('./inperialismoaren-faktoreak.html'+(accountIsTeacher()?'?preview=1':''));return;}if(currentMission===1&&(!galleryQuestionsOpen||!demo)&&!isTeacher())return renderGallery();const m=missionById(currentMission);if(!m)return;const done=!isTeacher()&&completed(viewTeamId(),m.id);const qs=m.questions||[];const answered=qs.filter(q=>responses[q.id]!==undefined).length;$("#view").innerHTML='<div class="content-width">'+pageHeading("MISIOA "+String(m.id).padStart(2,"0")+" · INPERIALISMOAREN HISTORIA",m.title,m.intro,done?'✓ OSATUTA':'AURRERA EGITEKO % 100')+'<div class="card"><div class="eyebrow">HASI AURRETIK</div><h3>'+esc(m.subtitle)+'</h3><p class="card-sub">Irakurri arretaz. '+qs.length+' galdera daude. Guztiak asmatu behar dituzu; ondo erantzundakoak gordeko dira, eta berriro saia zaitezke.</p><div class="progressbar"><span style="width:'+(qs.length?100*qs.filter(q=>checkFeedback?.correct?.includes(q.id)).length/qs.length:0)+'%"></span></div><div class="card-sub">'+answered+' / '+qs.length+' erantzunda</div></div>'+qs.map((q,i)=>'<section class="card question-card"><div class="eyebrow">GALDERA '+String(i+1).padStart(2,"0")+'</div><div class="question-title">'+esc(q.text)+'</div><div class="question-options">'+q.options.map((opt,j)=>'<label class="option '+(checkFeedback?.correct?.includes(q.id)&&responses[q.id]===j?'locked-correct':'')+'"><input type="radio" name="question-'+esc(q.id)+'" value="'+j+'" data-question="'+esc(q.id)+'" '+(responses[q.id]===j?'checked':'')+' '+(checkFeedback?.correct?.includes(q.id)||done||isTeacher()?'disabled':'')+'><span>'+esc(opt)+'</span></label>').join("")+'</div>'+(checkFeedback?.correct?.includes(q.id)?'<div class="question-feedback ok">✓ Erantzun zuzena</div>':checkFeedback?.incorrect?.includes(q.id)?'<div class="question-feedback bad">Berrikusi erantzuna eta saiatu berriro.</div>':'')+'</section>').join("")+(done?'<div class="complete-banner"><h3>✓ Misioa gaindituta!</h3><p>Zuen taldeak erantzun guztiak asmatu ditu. Hurrengo misioa desblokeatu da.</p><button class="btn primary" data-mission="'+Math.min(m.id+1,6)+'">Espedizioarekin jarraitu →</button></div>':isTeacher()?'<div class="notice">Irakaslearen aurrebista. Erantzunak ez dira pantaila honetatik bidaltzen.</div>':'<div class="mission-actions"><button class="btn primary" id="check-mission" '+(answered!==qs.length?'disabled':'')+'>Egiaztatu '+qs.length+' erantzunak →</button><span class="card-sub">Saiakera mugagabeak · Aurrerapena gordeta</span></div>')+'</div>';
}
async function submitMission(){if(teacherPreview)return toast("Aurrebista: erabili probako ikasle-kontu bat benetako zuzenketa probatzeko.");const m=missionById(currentMission);if(!m||!user||isTeacher())return;if(m.id===1)return toast("Lehen misioa bost ariketa interaktiboak gainditzean osatzen da.");const qs=m.questions||[];if(qs.some(q=>responses[q.id]===undefined))return toast("Erantzun galdera guztiei.");let correct=[],incorrect=[],complete=false,attemptNo=0;
if(demo){correct=qs.filter(q=>Number(responses[q.id])===q.correct).map(q=>q.id);incorrect=qs.filter(q=>!correct.includes(q.id)).map(q=>q.id);attemptNo=attempts.filter(a=>a.team_id===viewTeamId()&&a.mission_id===m.id).length+1;attempts.push({team_id:viewTeamId(),mission_id:m.id,created_at:time(),correct_count:correct.length});complete=correct.length===qs.length;if(complete&&!completed(viewTeamId(),m.id))progress.push({team_id:viewTeamId(),mission_id:m.id,completed_by:user.id,completed_at:time(),attempt_count:attemptNo});storage.save()}
else{try{const payload=Object.fromEntries(Object.entries(responses).map(([k,v])=>[k,v]));const {data,error}=await db.rpc("submit_mission",{p_mission_id:m.id,p_answers:payload});if(error)throw error;correct=data.correct||[];incorrect=data.incorrect||[];complete=!!data.completed;attemptNo=data.attempt_count||0;await refreshData()}catch(e){toast("Ezin izan dira erantzunak zuzendu: "+e.message);return}}
checkFeedback={correct,incorrect};if(complete){render();modal('<div class="eyebrow">MISIOA GAINDITUTA</div><h2 id="modal-title">Erantzun guztiak zuzen! ✓</h2><p>Habéis conseguido '+qs.length+' de '+qs.length+' erantzun zuzen lortu dituzue '+attemptNo+' saiakeratan. Hurrengo misioa desblokeatuta dago eta zuen taldeak marka berdea du.</p><button class="btn primary full" data-next="'+Math.min(m.id+1,6)+'">Jarraitu →</button>');toast("Misioa gaindituta!")}else{render();toast(correct.length+" / "+qs.length+" erantzun zuzen dituzue. Berrikusi gainerakoak.")}}
function renderFinal(){const done=completed(viewTeamId(),5);if(!isTeacher()&&!done){currentMission=5;return render()}const ownClaim=claims.find(c=>String(c.team_id)===String(viewTeamId()));const ownSubmission=submissions.filter(s=>String(s.team_id)===String(viewTeamId())).at(-1);const total=territories.filter(t=>t.continent===continent).length;$("#view").innerHTML='<div class="content-width">'+pageHeading("MISIÓN 06 · DESAFÍO FINAL","El reparto y sus consecuencias","Una simulación crítica para reflexionar sobre la apropiación colonial. Elige un territorio disponible y entrega vuestra investigación histórica en PDF.","ETAPA FINAL")+'<div class="notice amber"><strong>Reflexión histórica:</strong> la reclamación de países es una simulación educativa. Los países actuales, representados con banderas contemporáneas, no equivalen a las colonias y fronteras del siglo XIX. Los pueblos colonizados tenían historia y agencia propias.</div><div class="stats-grid"><div class="card"><div class="stat-number">'+claims.length+'</div><div class="stat-label">Territorios reclamados</div></div><div class="card"><div class="stat-number">'+(territories.length-claims.length)+'</div><div class="stat-label">Territorios disponibles</div></div><div class="card"><div class="stat-number">'+submissions.length+'</div><div class="stat-label">Entregas registradas</div></div></div><h3 class="section-title">01 / Seleccionad un territorio</h3><div class="two-col"><div class="card"><div class="continent-tabs"><button class="btn '+(continent==="Africa"?'primary':'outline')+'" data-continent="Africa">África</button><button class="btn '+(continent==="Asia"?'primary':'outline')+'" data-continent="Asia">Asia</button></div><div class="map-wrap" id="world-map"><div class="map-loading">Cargando mapa interactivo…</div></div><p class="map-caption">Haz clic en un país del mapa o selecciónalo en la lista. Los colores distinguen territorios libres y reclamados.</p></div><div class="card"><div class="eyebrow">TERRITORIOS · '+(continent==="Africa"?"ÁFRICA":"ASIA")+'</div><h3>'+total+' países para explorar</h3><p class="card-sub">Una elección por equipo (regla inicial modificable por el profesor). La selección se bloquea al confirmarse.</p><div class="territory-controls" id="territory-list">'+territories.filter(t=>t.continent===continent).sort((a,b)=>a.name.localeCompare(b.name,"es")).map(t=>{const claim=claims.find(c=>c.country_code===t.code);const owner=teams.find(x=>x.id===claim?.team_id);return '<button type="button" class="territory-item '+(selectedCountry===t.code?'active':'')+'" data-country="'+t.code+'" '+(claim||ownClaim||isTeacher()?'disabled':'')+'><span><span class="territory-flag">'+flag(t.code)+'</span> '+esc(t.name)+'</span><span class="'+(claim?'status-taken':'status-free')+'">'+(claim?'✓ '+esc(owner?.name||"Ocupado"):'Libre')+'</span></button>'}).join("")+'</div>'+(ownClaim?'<div class="notice success">✓ Vuestro equipo ha elegido '+esc(territories.find(t=>t.code===ownClaim.country_code)?.name||ownClaim.country_code)+'.</div>':'')+'<button class="btn primary full" id="claim-button" '+(!selectedCountry||ownClaim||isTeacher()?'disabled':'')+'>Confirmar territorio →</button></div></div><h3 class="section-title">02 / Entrega del trabajo final</h3><div class="card"><div class="two-col"><div><h3>Presentación histórica en PDF</h3><p class="card-sub">Preparad una presentación en PowerPoint y exportadla a PDF (máximo 20 MB). Incluid las causas del imperialismo, potencias, reparto, consecuencias y una reflexión crítica.</p><ul class="list-small"><li>Explicación histórica con fuentes citadas.</li><li>Mapa y datos contextualizados.</li><li>Perspectivas de las poblaciones colonizadas.</li><li>Conclusiones elaboradas por el equipo.</li></ul></div><div><div class="upload-area"><h3>↑ Subid vuestro PDF</h3><form id="upload-form"><input type="file" id="pdf-input" accept=".pdf,application/pdf" required '+(isTeacher()||teacherPreview?'disabled':'')+'><button type="submit" class="btn primary full" '+(isTeacher()||teacherPreview?'disabled':'')+'>Entregar trabajo →</button></form><p class="card-sub">Archivo .pdf · Máximo 20 MB</p></div>'+(ownSubmission?'<p class="review-status">✓ Último PDF entregado: '+fmt(ownSubmission.created_at)+' · '+esc(ownSubmission.status||"Pendiente de revisión")+'</p>':'')+'</div></div></div><p class="footer-note">En modo demostración, los PDF no se suben a ningún servidor; únicamente se simula el registro de entrega.</p></div>';renderMap();}
async function claimCountry(code){if(teacherPreview)return toast("Vista previa: no se reclamará ningún territorio.");if(isTeacher()||claims.some(c=>c.team_id===viewTeamId()))return;const t=territories.find(t=>t.code===code);if(!t||claims.some(c=>c.country_code===code))return toast("Este país ya ha sido reclamado.");modal('<div class="eyebrow">ELECCIÓN TERRITORIAL</div><h2 id="modal-title">¿Confirmar '+flag(code)+' '+esc(t.name)+'?</h2><p>El territorio aparecerá con el nombre de <strong>'+esc(mine()?.name)+'</strong> y dejará de estar disponible para los demás equipos.</p><div class="notice amber">Esta elección representa una simulación crítica del reparto colonial, no una posesión real.</div><button class="btn primary full" data-confirm-country="'+code+'">Confirmar reclamación</button>')}
async function confirmClaim(code){if(teacherPreview)return toast("Vista previa: no se guardan reclamaciones.");try{if(demo){if(claims.some(c=>c.country_code===code||c.team_id===viewTeamId()))throw Error("Territorio ya reclamado o equipo sin turno disponible.");claims.push({country_code:code,team_id:viewTeamId(),claimed_at:time()});storage.save()}else{const {error}=await db.rpc("claim_territory",{p_country_code:code});if(error)throw error;await refreshData()}closeModal();selectedCountry=null;render();toast("Territorio registrado y bloqueado para otros equipos.")}catch(e){closeModal();toast("No se pudo reclamar: "+e.message);await refreshData();render()}}
async function uploadPdf(e){e.preventDefault();if(teacherPreview)return toast("Vista previa: no se guardan archivos.");if(isTeacher())return;const input=$("#pdf-input"),file=input?.files?.[0];if(!file)return;if(file.size>20*1024*1024)return toast("El PDF supera los 20 MB.");if(file.type!=="application/pdf"&&!file.name.toLowerCase().endsWith(".pdf"))return toast("Solo se admiten PDF.");try{if(demo){submissions.push({team_id:viewTeamId(),created_at:time(),filename:file.name,status:"Simulación (sin archivo almacenado)",file_path:null});storage.save()}else{const path=viewTeamId()+"/"+crypto.randomUUID()+".pdf";const {error}=await db.storage.from("entregas").upload(path,file,{contentType:"application/pdf",upsert:false});if(error)throw error;const {error:recordError}=await db.rpc("register_submission",{p_path:path,p_filename:file.name,p_size:file.size});if(recordError)throw recordError;await refreshData()}render();toast(demo?"Entrega simulada (el archivo no se ha guardado).":"PDF entregado correctamente.")}catch(err){toast("No se pudo enviar: "+err.message)}}
async function renderMap(){const host=$("#world-map");if(!host)return;const list=territories.filter(t=>t.continent===continent);try{const [d3,topo]=await Promise.all([import("https://cdn.jsdelivr.net/npm/d3-geo@3/+esm"),import("https://cdn.jsdelivr.net/npm/topojson-client@3/+esm")]);const res=await fetch("https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json");if(!res.ok)throw Error("Mapa no disponible");const topology=await res.json();if(!$("#world-map"))return;const features=topo.feature(topology,topology.objects.countries).features;
const codeMap={"Algeria":"DZ","Angola":"AO","Benin":"BJ","Botswana":"BW","Burkina Faso":"BF","Burundi":"BI","Cameroon":"CM","Cape Verde":"CV","Central African Republic":"CF","Chad":"TD","Comoros":"KM","Democratic Republic of the Congo":"CD","Republic of the Congo":"CG","Congo":"CG","Ivory Coast":"CI","Djibouti":"DJ","Egypt":"EG","Equatorial Guinea":"GQ","Eritrea":"ER","eSwatini":"SZ","Eswatini":"SZ","Ethiopia":"ET","Gabon":"GA","Gambia":"GM","Ghana":"GH","Guinea":"GN","Guinea-Bissau":"GW","Kenya":"KE","Lesotho":"LS","Liberia":"LR","Libya":"LY","Madagascar":"MG","Malawi":"MW","Mali":"ML","Mauritania":"MR","Mauritius":"MU","Morocco":"MA","Mozambique":"MZ","Namibia":"NA","Niger":"NE","Nigeria":"NG","Rwanda":"RW","São Tomé and Principe":"ST","Senegal":"SN","Seychelles":"SC","Sierra Leone":"SL","Somalia":"SO","South Africa":"ZA","South Sudan":"SS","Sudan":"SD","Tanzania":"TZ","Togo":"TG","Tunisia":"TN","Uganda":"UG","Zambia":"ZM","Zimbabwe":"ZW","Afghanistan":"AF","Saudi Arabia":"SA","Armenia":"AM","Azerbaijan":"AZ","Bahrain":"BH","Bangladesh":"BD","Bhutan":"BT","Brunei":"BN","Cambodia":"KH","China":"CN","Cyprus":"CY","Georgia":"GE","India":"IN","Indonesia":"ID","Iran":"IR","Iraq":"IQ","Israel":"IL","Japan":"JP","Jordan":"JO","Kazakhstan":"KZ","Kuwait":"KW","Kyrgyzstan":"KG","Laos":"LA","Lebanon":"LB","Malaysia":"MY","Maldives":"MV","Mongolia":"MN","Myanmar":"MM","Nepal":"NP","North Korea":"KP","South Korea":"KR","Oman":"OM","Pakistan":"PK","Palestine":"PS","Philippines":"PH","Qatar":"QA","Russia":"RU","Singapore":"SG","Sri Lanka":"LK","Syria":"SY","Taiwan":"TW","Tajikistan":"TJ","Thailand":"TH","Timor-Leste":"TL","Turkey":"TR","Turkmenistan":"TM","United Arab Emirates":"AE","Uzbekistan":"UZ","Vietnam":"VN","Yemen":"YE"};
const active=features.filter(f=>{const c=codeMap[f.properties?.name];return c&&list.some(t=>t.code===c)});const projection=d3.geoNaturalEarth1().fitExtent([[15,18],[765,415]],{type:"FeatureCollection",features:active});const path=d3.geoPath(projection);const pieces=active.map(f=>{const c=codeMap[f.properties.name],t=list.find(t=>t.code===c),cl=claims.find(x=>x.country_code===c);return '<path class="country '+(cl?'taken':selectedCountry===c?'selected':'available')+'" data-country="'+esc(c)+'" d="'+esc(path(f))+'"><title>'+esc(t?.name||c)+' — '+(cl?esc(teams.find(x=>x.id===cl.team_id)?.name||"Reclamado"):"Libre")+'</title></path>'}).join("");host.innerHTML='<svg viewBox="0 0 780 440" role="img" aria-label="Mapa interactivo de '+(continent==="Africa"?"África":"Asia")+'; elige un territorio o usa la lista accesible">'+pieces+'</svg>';if(!pieces)throw Error("Sin geometrías")}catch(e){host.innerHTML='<div class="empty" style="margin:40px 16px">No se ha podido cargar el mapa gráfico. Puedes seleccionar un país usando la lista de la derecha.</div>'}}
